package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.net.Uri;
import android.graphics.Bitmap;
import org.json.*;
import okhttp3.*;
import java.io.*;
import java.util.concurrent.TimeUnit;
/** Bounded uploads. Videos stay in quarantine until server review succeeds. */
final class FeedMedia {
 static final long VIDEO_LIMIT=200L*1024*1024;
 private static final String BACKEND=NativeBackend.ORIGIN;
 private static final OkHttpClient HTTP=new OkHttpClient.Builder().followRedirects(false).followSslRedirects(false).connectTimeout(15,TimeUnit.SECONDS).readTimeout(180,TimeUnit.SECONDS).writeTimeout(90,TimeUnit.SECONDS).build();
 static String upload(Context c,Uri uri,String user,String token,String[] cfg)throws Exception{
  checkSession(c,user,token);String mime=c.getContentResolver().getType(uri);if(mime==null)throw new IOException("Formato de arquivo desconhecido.");boolean video=mime.equals("video/mp4")||mime.equals("video/webm");if(!video&&!mime.equals("image/jpeg")&&!mime.equals("image/png")&&!mime.equals("image/webp"))throw new IOException("Escolha JPG, PNG, WebP, MP4 ou WebM.");String ext=video?(mime.equals("video/mp4")?"mp4":"webm"):"jpg",path=user+"/"+java.util.UUID.randomUUID()+"."+ext;
  if(!video){Bitmap image=ProfileImages.decode(c,uri);ByteArrayOutputStream data=new ByteArrayOutputStream();image.compress(Bitmap.CompressFormat.JPEG,92,data);image.recycle();byte[] bytes=data.toByteArray();if(bytes.length>10*1024*1024)throw new IOException("Imagem maior que 10 MB.");confirmed(request(BACKEND+"/api/media/upload?bucket=feed-media&path="+java.net.URLEncoder.encode(path,"UTF-8"),"POST",RequestBody.create(bytes,MediaType.get("image/jpeg")),token),path);}
  else {File temporary=File.createTempFile("feed-video-",".tmp",c.getCacheDir());try{long size=0;try(InputStream in=c.getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(temporary)){if(in==null)throw new IOException("Não foi possível abrir o vídeo.");byte[] block=new byte[65536];int n;while((n=in.read(block))!=-1){size+=n;if(size>VIDEO_LIMIT)throw new IOException("Vídeos podem ter até 200 MB.");out.write(block,0,n);}}if(size==0)throw new IOException("Vídeo vazio.");String host=new java.net.URI(cfg[0]).getHost().replace(".supabase.co",".storage.supabase.co"),endpoint="https://"+host+"/storage/v1/upload/resumable";String metadata="bucketName "+b64("clt-quarantine")+",objectName "+b64(path)+",contentType "+b64(mime)+",cacheControl "+b64("3600");Request create=new Request.Builder().url(endpoint).header("Authorization","Bearer "+token).header("Tus-Resumable","1.0.0").header("Upload-Length",String.valueOf(size)).header("Upload-Metadata",metadata).header("x-upsert","false").post(RequestBody.create(new byte[0],null)).build();String location;try(Response r=HTTP.newCall(create).execute()){if(r.code()!=201)throw new IOException("Criação do envio falhou (HTTP "+r.code()+").");location=r.header("Location");}if(location==null)throw new IOException("Envio sem endereço de confirmação.");HttpUrl base=HttpUrl.get(endpoint),target=base.resolve(location);if(target==null||!target.isHttps()||!host.equals(target.host())||!target.encodedPath().startsWith("/storage/v1/upload/resumable/"))throw new IOException("Endereço de envio inválido.");long offset=0;try(InputStream in=new FileInputStream(temporary)){byte[] chunk=new byte[6*1024*1024];while(offset<size){checkSession(c,user,token);int count=0,want=(int)Math.min(chunk.length,size-offset);while(count<want){int n=in.read(chunk,count,want-count);if(n<0)throw new EOFException();count+=n;}Request patch=new Request.Builder().url(target).header("Authorization","Bearer "+token).header("Tus-Resumable","1.0.0").header("Upload-Offset",String.valueOf(offset)).patch(RequestBody.create(MediaType.get("application/offset+octet-stream"),chunk,0,count)).build();try(Response r=HTTP.newCall(patch).execute()){if(r.code()!=204||!String.valueOf(offset+count).equals(r.header("Upload-Offset")))throw new IOException("Vídeo sem confirmação de envio. Atualize o feed antes de tentar novamente.");}offset+=count;}}
   checkSession(c,user,token);confirmed(request(BACKEND+"/api/media/video-review","POST",RequestBody.create(new JSONObject().put("path",path).toString(),MediaType.get("application/json")),token),path);
  }finally{temporary.delete();}}
  return cfg[0]+"/storage/v1/object/public/feed-media/"+path;
 }
 private static void checkSession(Context c,String user,String token)throws IOException{android.content.SharedPreferences p=c.getSharedPreferences("batcaverna",0);if(!user.equals(p.getString("user_id",""))||!token.equals(p.getString("access_token","")))throw new IOException("Sua sessão mudou. O envio foi interrompido.");}
 private static String b64(String value){return android.util.Base64.encodeToString(value.getBytes(java.nio.charset.StandardCharsets.UTF_8),android.util.Base64.NO_WRAP);}
 static JSONObject request(String url,String method,RequestBody body,String token)throws Exception{Request req=new Request.Builder().url(url).header("Authorization","Bearer "+token).method(method,body).build();try(Response response=HTTP.newCall(req).execute()){if(!response.isSuccessful())throw new IOException("Arquivo não aprovado ou serviço indisponível (HTTP "+response.code()+").");if(response.body()==null)throw new IOException("Resposta vazia.");try(InputStream input=response.body().byteStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=input.read(b))!=-1){if(out.size()+n>1024*1024)throw new IOException("Resposta inválida.");out.write(b,0,n);}return new JSONObject(out.toString("UTF-8"));}}}
 private static void confirmed(JSONObject reply,String path)throws IOException{JSONObject data=reply.optJSONObject("data");if(data==null||!path.equals(data.optString("path"))||!reply.isNull("error"))throw new IOException("Moderação sem confirmação. O arquivo não foi publicado.");}
 static String playable(String url,String token,String[] cfg)throws Exception{String prefix=cfg[0]+"/storage/v1/object/public/feed-media/";if(!url.startsWith(prefix))throw new IOException("Vídeo fora do armazenamento autorizado.");String path=url.substring(prefix.length());JSONObject reply=request(BACKEND+"/api/media/prepare","POST",RequestBody.create(new JSONObject().put("bucket","feed-media").put("path",path).toString(),MediaType.get("application/json")),token);String signed=reply.optString("signedUrl");HttpUrl target=HttpUrl.parse(signed);String host=new java.net.URI(cfg[0]).getHost();if(target==null||!target.isHttps()||!(host.equals(target.host())||host.replace(".supabase.co",".storage.supabase.co").equals(target.host())))throw new IOException("Vídeo ainda indisponível.");return signed;}
}
